import os, pathlib, subprocess, sys
root = pathlib.Path.cwd().resolve()
def confined(path):
    path = pathlib.Path(path)
    if not path.resolve().is_relative_to(root):
        sys.exit('Selected path escapes worktree: ' + str(path))
    return path
def run(args, cwd):
    subprocess.run(args, cwd=cwd, check=True)
import json, shutil
excluded = {'.git', '.venv', 'venv', 'env', 'node_modules', 'dist', 'build', 'coverage', 'htmlcov', '__pycache__', '.cache', '.next', '.nuxt', '.output', 'vendor', '.tox', '.nox', '.mypy_cache', '.pytest_cache', '.ruff_cache'}
packages = []
for current, dirs, files in os.walk(root):
    dirs[:] = sorted(name for name in dirs if name not in excluded)
    for name in dirs:
        confined(pathlib.Path(current) / name)
    if 'package.json' in files:
        location = confined(pathlib.Path(current))
        manifest = confined(location / 'package.json')
        packages.append((location, json.loads(manifest.read_text())))
if packages:
    for tool in ('node', 'npm'):
        if shutil.which(tool) is None:
            sys.exit('Missing required executable: ' + tool)
for location, package in packages:
    confined(location / 'node_modules')
    cache = confined(location / '.cache' / 'npm')
    lock = confined(location / 'package-lock.json')
    run(['npm', 'ci' if lock.is_file() else 'install', '--engine-strict', '--ignore-scripts', '--cache', str(cache)], location)

